class Solution:
    def dailyTemperatures(self, t: list[int]) -> list[int]:
        n = len(t)
        stack = []
        ans = [0] * n
        for i in range(n):
            while stack and t[stack[-1]] < t[i]:
                idx = stack.pop()
                ans[idx] = i - idx
            stack.append(i)
        return ans
